mapper.select:
select * from ( select s.ID, s.TWINING_DISC_CODE, s.STEEL_RING_CODE, s.STEEL_RING_NAME, s.STATUS, s.FACTORY_CODE, s.DATA_VERSION, s.IS_DELETE, s.CREATE_BY, s.CREATE_TIME, s.UPDATE_BY, s.UPDATE_TIME, s.REMARK, d.TWINING_DISC_NAME, d.PRO_SIZE, d.SORT_TYPE from T_GSQ_TWINING_DISC_SPEC s left join T_GSQ_TWINING_DISC d on d.TWINING_DISC_CODE = s.TWINING_DISC_CODE and d.IS_DELETE = '0' where s.IS_DELETE = '0'
and INSTR(s.TWINING_DISC_CODE, #{twiningDiscCode}) > 0
and INSTR(s.STEEL_RING_CODE, #{steelRingCode}) > 0
and s.STATUS = #{status}
and s.FACTORY_CODE = #{factoryCode}
order by s.CREATE_TIME desc
) t
order by ${orderStr}

select count(1)
from T_GSQ_TWINING_DISC_SPEC
where IS_DELETE = '0'
  and TWINING_DISC_CODE = #{entity.twiningDiscCode}
  and STEEL_RING_CODE = #{entity.steelRingCode}

    and ID != #{entity.id}
